    48	    public static class TitanPassageUtility
    49	    {
    50	        public const string SeabedLayerDefName = "RM_SeabedLayer";
    51	        public const string SeabedFloorExtensionName = "RM_SeabedFloorExtension";
    52	
    53	        /// <summary>The 2026-10-21 card's gate, per kind: RM_TitanicKernel.TitanEventEligible over the live biome commonalities.
    54	        /// A calf kind of a titan race is judged by its race's adult tier, so it qualifies ("Calves are ok").</summary>
    55	        public static bool Eligible(PawnKindDef k, Map map, bool t3OnMap)
    56	        {
    57	            if (k?.race?.race == null || map == null || !k.RaceProps.Animal || k.RaceProps.Dryad) return false;
    58	            if (k.race.GetModExtension<RM_TitanicExtension>()?.harnessOnly == true) return false;
    59	            int tier = (int)TitanicTierUtility.AdultTier(k.race);
    60	            if (tier < RM_TitanicKernel.T2) return false;
    61	            bool optedOut = map.Biomes.Any(b => b?.GetModExtension<RM_TitanPassageExtension>()?.none == true);
    62	            bool hasList = false, onList = false;
    63	            foreach (BiomeDef b in map.Biomes)
    64	            {
    65	                List<PawnKindDef> list = b?.GetModExtension<RM_TitanPassageExtension>()?.passers;
    66	                if (list == null || list.Count == 0) continue;
    67	                hasList = true;
    68	                if (list.Contains(k)) onList = true;
    69	            }
    70	            bool here = map.Biomes.Any(b => b.CommonalityOfAnimal(k) > 0f);
    71	            bool season = map.mapTemperature.SeasonAndOutdoorTemperatureAcceptableFor(k.race);
    72	            return RM_TitanicKernel.TitanEventEligible(tier, optedOut, IsSeaCreature(k), IsSeaMap(map), hasList, onList, here,
    73	                season, t3OnMap);
    74	        }
