    76	        /// <summary>A sea biome: a water biome (Grey Sea, Twilight Sea, the Scald, the Chill...) or a seabed floor, whose cast is
    77	        /// its sea's (RM_SeabedFloorLife copies it at startup). The floor test is by extension type name on purpose: this
    78	        /// assembly must not depend on DivingInteraction.</summary>
    79	        public static bool IsSeaBiome(BiomeDef b)
    80	        {
    81	            if (b == null) return false;
    82	            if (b.isWaterBiome) return true;
    83	            if (b.modExtensions != null)
    84	                foreach (DefModExtension e in b.modExtensions)
    85	                    if (e != null && e.GetType().Name == SeabedFloorExtensionName) return true;
    86	            return false;
    87	        }
    88	
    89	        /// <summary>A sea map: its own biome is a sea biome, or it lies on the seabed planet layer (name test, as
    90	        /// RM_SurfaceHome.IsSeabedMap).</summary>
    91	        public static bool IsSeaMap(Map map)
    92	        {
    93	            if (map == null) return false;
    94	            if (map.Tile.Valid && map.Tile.Layer?.Def?.defName == SeabedLayerDefName) return true;
    95	            return IsSeaBiome(map.Biome);
    96	        }
