   100	        /// <summary>A sea creature: homed in at least one biome, and only ever in sea biomes. Cached per kind (rosters are fixed
   101	        /// after def load).</summary>
   102	        public static bool IsSeaCreature(PawnKindDef k)
   103	        {
   104	            if (k == null) return false;
   105	            if (seaCache == null) seaCache = new Dictionary<PawnKindDef, bool>();
   106	            if (seaCache.TryGetValue(k, out bool v)) return v;
   107	            int sea = 0, land = 0;
   108	            foreach (BiomeDef b in DefDatabase<BiomeDef>.AllDefsListForReading)
   109	            {
   110	                if (b.CommonalityOfAnimal(k) <= 0f) continue;
   111	                if (IsSeaBiome(b)) sea++; else land++;
   112	            }
   113	            v = RM_TitanicKernel.IsSeaCreature(sea, land);
   114	            seaCache[k] = v;
   115	            return v;
   116	        }
