   129	        /// <summary>The herd-migration route: an entry cell and the reachable edge cell farthest from it.</summary>
   130	        public static bool TryFindStartAndEnd(Map map, out IntVec3 start, out IntVec3 end)
   131	        {
   132	            end = IntVec3.Invalid;
   133	            if (!RCellFinder.TryFindRandomPawnEntryCell(out start, map, CellFinder.EdgeRoadChance_Animal)) return false;
   134	            IntVec3 s = start;
   135	            for (int i = 0; i < 8; i++)
   136	            {
   137	                if (!CellFinder.TryFindRandomEdgeCellWith(x => map.reachability.CanReach(s, x, PathEndMode.OnCell,
   138	                        TraverseParms.For(TraverseMode.PassDoors)), map, CellFinder.EdgeRoadChance_Ignore, out IntVec3 r)) break;
   139	                if (!end.IsValid || r.DistanceToSquared(start) > end.DistanceToSquared(start)) end = r;
   140	            }
   141	            return end.IsValid;
   142	        }
