   144	        public static string EdgeName(Map map, IntVec3 c)
   145	        {
   146	            int dx = Mathf.Min(c.x, map.Size.x - 1 - c.x), dz = Mathf.Min(c.z, map.Size.z - 1 - c.z);
   147	            if (dx < dz) return (c.x < map.Size.x / 2 ? "RM_TitanPassage_West" : "RM_TitanPassage_East").Translate();
   148	            return (c.z < map.Size.z / 2 ? "RM_TitanPassage_South" : "RM_TitanPassage_North").Translate();
   149	        }
