   152	    /// <summary>The scheduled passages of one map: tremors through the warning, then the titan walks in.</summary>
   153	    public class MapComponent_TitanPassages : MapComponent
   154	    {
   155	        private const int ShakeInterval = 300;
   156	        private const int MessageInterval = 2 * GenDate.TicksPerHour;
   157	
   158	        private PawnKindDef kind;
   159	        private IntVec3 start = IntVec3.Invalid, end = IntVec3.Invalid;
   160	        private int arrivalTick = -1, warnedTick = -1, warningTicks;
   161	        private Pawn arrived;
   162	
   163	        public MapComponent_TitanPassages(Map map) : base(map) { }
   164	
   165	        public bool HasPending => kind != null && arrivalTick >= 0;
   166	        public PawnKindDef PendingKind => kind;
   167	        public int ArrivalTick => arrivalTick;
   168	        public Pawn LastArrived => arrived;
   169	
   170	        public void Schedule(PawnKindDef k, IntVec3 s, IntVec3 e, int warning)
   171	        {
   172	            kind = k; start = s; end = e; warningTicks = warning;
   173	            int now = Find.TickManager.TicksGame;
   174	            arrivalTick = now + warning; warnedTick = now;
   175	        }
   176	
   177	        /// <summary>Validation hook: bring the arrival forward to the next tick.</summary>
   178	        public void DebugArriveNow() { if (HasPending) arrivalTick = Find.TickManager.TicksGame; }
   179	
   180	        public override void MapComponentTick()
   181	        {
   182	            if (!HasPending) return;
   183	            int now = Find.TickManager.TicksGame;
   184	            if (now >= arrivalTick) { Arrive(); return; }
   185	            if (now % ShakeInterval == 0 && Find.CurrentMap == map)
   186	            {
   187	                // Footfall: stronger the nearer it comes (0.3 at the first tremor, 1.5 at arrival).
   188	                float progress = warningTicks > 0 ? 1f - (arrivalTick - now) / (float)warningTicks : 1f;
   189	                Find.CameraDriver.shaker.DoShake(Mathf.Lerp(0.3f, 1.5f, Mathf.Clamp01(progress)));
   190	            }
   191	            if (now - warnedTick >= MessageInterval)
   192	            {
   193	                warnedTick = now;
   194	                Messages.Message("RM_TitanPassage_TremorStronger".Translate(), new TargetInfo(start, map), MessageTypeDefOf.NeutralEvent);
   195	            }
   196	        }
   197	
   198	        private void Arrive()
   199	        {
   200	            PawnKindDef k = kind;
   201	            IntVec3 s = start, e = end;
   202	            Clear();
   203	            // the warned edge is kept while it is still standable and reaches the far edge; otherwise a fresh route is found
   204	            bool routeOk = s.IsValid && e.IsValid && s.InBounds(map) && s.Standable(map)
   205	                           && map.reachability.CanReach(s, e, PathEndMode.OnCell, TraverseParms.For(TraverseMode.PassDoors));
   206	            if (!routeOk) routeOk = TitanPassageUtility.TryFindStartAndEnd(map, out s, out e);
   207	            if (!RM_HugeThingsSettings.TitanEventsActive || !TitanPassageUtility.Eligible(k, map, TitanPassageUtility.T3OnMap(map)) || !routeOk)
   208	            {
   209	                Messages.Message("RM_TitanPassage_Faded".Translate(), MessageTypeDefOf.NeutralEvent);
   210	                return;
   211	            }
   212	            Pawn titan = PawnGenerator.GeneratePawn(new PawnGenerationRequest(k, null, PawnGenerationContext.NonPlayer, map.Tile));
   213	            GenSpawn.Spawn(titan, CellFinder.RandomClosewalkCellNear(s, map, 8), map, Rot4.FromAngleFlat((map.Center - s).AngleFlat));
   214	            LordMaker.MakeNewLord(null, new LordJob_ExitMapNear(e, LocomotionUrgency.Walk), map, new List<Pawn> { titan });
   215	            arrived = titan;
   216	            Find.LetterStack.ReceiveLetter("RM_TitanPassage_ArriveLabel".Translate(titan.LabelShortCap),
   217	                "RM_TitanPassage_ArriveText".Translate(titan.LabelShort), LetterDefOf.ThreatSmall, titan);
   218	        }
   219	
   220	        private void Clear()
   221	        {
   222	            kind = null; arrivalTick = -1; warnedTick = -1; start = IntVec3.Invalid; end = IntVec3.Invalid;
   223	        }
   224	
   225	        public override void ExposeData()
   226	        {
   227	            base.ExposeData();
   228	            Scribe_Defs.Look(ref kind, "rmTitanKind");
   229	            Scribe_Values.Look(ref start, "rmTitanStart", IntVec3.Invalid);
   230	            Scribe_Values.Look(ref end, "rmTitanEnd", IntVec3.Invalid);
   231	            Scribe_Values.Look(ref arrivalTick, "rmTitanArrival", -1);
   232	            Scribe_Values.Look(ref warnedTick, "rmTitanWarned", -1);
   233	            Scribe_Values.Look(ref warningTicks, "rmTitanWarningTicks", 0);
   234	            Scribe_References.Look(ref arrived, "rmTitanArrived");
   235	            if (Scribe.mode == LoadSaveMode.PostLoadInit && kind == null) arrivalTick = -1;
   236	        }
   237	    }
