            // WorkGiver_Tend is a base class, not a registered worker. Select the
            // actual vanilla WorkGiverDef (Core/Defs/WorkGiverDefs/WorkGivers.xml).
            string giverName = a[2] == "feed" ? "FeedPrisoner" : a[2] == "deliver"
